accdet(id){const a=S.acc.find(v=>v.id===id);if(!a)return;const g={},all=txs().filter(x=>x.a===id||x.to===id);let vd=0;
let fut=0;for(const x of all){if(x.st!=='ok'){vd++;continue}if(x.d>today()){fut++;continue}let k,d;if(x.ty==='transfer'){k=x.a===id?'tout':'tin';d=x.a===id?-x.amt:x.amt}else{k=x.ty;d=eff(x)}const r=g[k]=g[k]||{n:0,t:0n};r.n++;r.t+=d}
const O=['income','tin','capital','loan_in','refund','adjp','expense','tout','draw','loan_prin','loan_int','adjm'],lb=k=>k==='tin'?'Transfer masuk':k==='tout'?'Transfer keluar':T[k].l;
const rows=Object.keys(g).sort((x,y)=>O.indexOf(x)-O.indexOf(y)).map(k=>`<tr><td>${lb(k)}<small>${g[k].n} transaksi</small></td><td class="${g[k].t<0n?'neg':'pos'}">${g[k].t>0n?'+':''}${rp(g[k].t)}</td></tr>`).join('');
sheet(`<h2>${esc(a.name)}</h2><small>Rincian saldo rekening</small><div class="c"><table><tr><td>Saldo awal<small>${a.src&&a.src.length?'Terdiri dari '+a.src.length+' sumber':a.note?esc(a.note):'Uang yang sudah ada sebelum mulai mencatat'}</small></td><td>${rp(a.open)}</td></tr>${(a.src||[]).map(v=>`<tr class="sub"><td>${esc(v.n)}</td><td>${rp(v.amt)}</td></tr>`).join('')}${rows}<tr><td><b>Saldo sekarang</b></td><td>${rp(bal(a))}</td></tr></table><small class="hint">Saldo sekarang = saldo awal ditambah semua transaksi sah di rekening ini.${vd?' '+vd+' transaksi dibatalkan tidak dihitung.':''}${fut?' '+fut+' transaksi bertanggal masa depan belum dihitung sampai tanggalnya tiba.':''} Saldo awal dicatat sebagai ekuitas awal, bukan pendapatan.</small></div><h3>Transaksi terbaru rekening ini</h3>${list(all.sort(cmp).slice(0,10))}<div class="row"><button class="btn" data-a="accnew:${a.id}">Ubah nama dan saldo awal</button><button class="btn ghost" data-a="close">Tutup</button></div>`)},
srcadd(){const id=uid(),b=$('#srcs');b.insertAdjacentHTML('beforeend','<div class="srow" id="r'+id+'"><input class="sn" maxlength="40" placeholder="Nama sumber, mis. Tabungan" aria-label="Nama sumber"><div><input class="sa" inputmode="numeric" placeholder="0" aria-label="Jumlah sumber"></div><button class="sx" data-a="srcdel:'+id+'" aria-label="Hapus sumber">×</button></div>');fmtInit();srcsum();b.lastElementChild.querySelector('.sn').focus()},
