accnew(p){const a=p?S.acc.find(v=>v.id===p):null;FM.acc=a?a.id:'';sheet(`<h2>${a?'Ubah':'Tambah'} rekening</h2><label>Nama<input id="an" maxlength="40" value="${esc(a?a.name:'')}"></label><label>Saldo awal (Rp)<input id="ao" inputmode="numeric" placeholder="0" value="${a&&a.open?a.open:''}"></label><h3>Rincian sumber saldo awal (opsional)</h3><small>Isi per sumber, misalnya tabungan atau deposito. Saldo awal di atas dihitung otomatis dari jumlahnya.</small><div id="srcs"></div><div class="row"><button class="btn ghost" data-a="srcadd">Tambah sumber</button></div><small class="hint">Saldo awal adalah uang yang sudah ada sebelum Anda mulai mencatat. Ini dicatat sebagai ekuitas awal, bukan pendapatan.</small><p id="err" class="neg"></p><div class="row"><button class="btn" data-a="accsave">Simpan</button><button class="btn ghost" data-a="close">Tutup</button></div>`);if(a&&a.src&&a.src.length){for(const v of a.src){act.srcadd();const r=$('#srcs').lastElementChild;r.querySelector('.sn').value=v.n;r.querySelector('.sa').value=v.amt;fmtNum(r.querySelector('.sa'))}srcsum()}},
