catnew(){sheet(`<h2>Tambah kategori</h2><label>Nama<input id="cn" maxlength="40"></label><label>Jenis<select id="ck"><option value="out">Pengeluaran</option><option value="in">Pendapatan</option></select></label><p id="err" class="neg"></p><div class="row"><button class="btn" data-a="catsave">Simpan</button><button class="btn ghost" data-a="catmgr">Kembali</button></div>`)},
